'use strict';
// Post-compilation patch: add Regulation M-B species and Mega forms to the
// Champions gen-0 dataset in @smogon/calc's compiled species.js.
//
// Upstream (smogon/damage-calc) is cloned at build time and may lag behind
// Champions regulation updates. This script appends a self-contained IIFE to
// the compiled dist/data/species.js that runs in module scope and has access
// to the module-local SPECIES_BY_ID map and Specie constructor.
//
// Usage: node patch-champions-mb.js <path-to-dist/data/species.js>

const fs = require('fs');
const filePath = process.argv[2];
if (!filePath) { console.error('Usage: node patch-champions-mb.js <species.js>'); process.exit(1); }

// New base species added in M-B (must exist in SV dataset).
const MB_BASE = [
  'Vileplume', 'Qwilfish', 'Overqwil',
  'Sceptile', 'Blaziken', 'Swampert',
  'Mawile', 'Metagross', 'Staraptor',
  'Musharna', 'Scolipede', 'Scrafty',
  'Eelektross', 'Pyroar', 'Malamar',
  'Barbaracle', 'Dragalge', 'Grimmsnarl',
  'Falinks', 'Houndstone', 'Annihilape', 'Gholdengo',
];

// Mega forms: keys are names, values are ability overrides (null = SV ability
// is already correct for Champions). Stats always come from SV data.
// Champions-specific abilities confirmed from official M-B announcements.
const MB_MEGAS = {
  'Blaziken-Mega':  null,                      // Speed Boost ✓
  'Sceptile-Mega':  null,                      // Lightning Rod ✓
  'Swampert-Mega':  null,                      // Swift Swim ✓
  'Mawile-Mega':    null,                      // Huge Power ✓
  'Metagross-Mega': null,                      // Tough Claws ✓
  'Staraptor-Mega': { 0: 'Contrary' },         // Champions: Contrary (SV: Intimidate)
  'Scolipede-Mega': { 0: 'Shell Armor' },      // Champions: Shell Armor (SV: Poison Point)
  'Scrafty-Mega':   { 0: 'Intimidate' },       // Champions: Intimidate (SV: Shed Skin)
  'Eelektross-Mega':{ 0: 'Levitate' },         // Champions: Eelevate (≈ Levitate; calc fallback)
  'Pyroar-Mega':    { 0: 'Fire Mane' },        // Champions: Fire Mane (new ability; no calc effect)
  'Malamar-Mega':   null,                      // Contrary ✓
  'Barbaracle-Mega':null,                      // Tough Claws ✓
  'Dragalge-Mega':  { 0: 'Regenerator' },      // Champions: Regenerator (SV: Poison Point)
  'Falinks-Mega':   { 0: 'Defiant' },          // Champions: Defiant (SV: Battle Armor)
};

// Build the IIFE that will be appended to species.js.
// It runs in module scope, so SPECIES_BY_ID, Specie, util_1 and exports are in scope.
const patch = `
// --- Champions Regulation M-B patch (auto-generated by patch-champions-mb.js) ---
(function () {
  var MB_BASE = ${JSON.stringify(MB_BASE)};
  var MB_MEGAS = ${JSON.stringify(MB_MEGAS)};
  var SV = exports.SPECIES[9];
  var CHAMPS = SPECIES_BY_ID[0];

  // Add new base species from SV data (same stats used in Champions).
  MB_BASE.forEach(function (name) {
    var id = util_1.toID(name);
    if (!CHAMPS[id] && SV[name]) {
      CHAMPS[id] = new Specie(name, SV[name]);
    }
  });

  // Add Mega forms: SV stats + Champions ability overrides where needed.
  Object.keys(MB_MEGAS).forEach(function (name) {
    var id = util_1.toID(name);
    if (!CHAMPS[id] && SV[name]) {
      var svData = SV[name];
      var abilityOverride = MB_MEGAS[name];
      var data = abilityOverride
        ? Object.assign({}, svData, { abilities: abilityOverride })
        : svData;
      CHAMPS[id] = new Specie(name, data);
    }
  });
})();
// --- end Champions M-B patch ---
`;

let content = fs.readFileSync(filePath, 'utf8');

if (content.includes('Champions Regulation M-B patch')) {
  console.log('Patch already applied, skipping.');
  process.exit(0);
}

// Insert before the sourcemap comment (or append if not present).
const MAP_COMMENT = '//# sourceMappingURL=species.js.map';
if (content.includes(MAP_COMMENT)) {
  content = content.replace(MAP_COMMENT, patch + '\n' + MAP_COMMENT);
} else {
  content += '\n' + patch;
}

fs.writeFileSync(filePath, content, 'utf8');
console.log('M-B patch applied to', filePath);
